<?php
require_once dirname(__DIR__,3).'/core/Session/AsiloSession.php'; require_once dirname(__DIR__,3).'/core/Security/CsrfToken.php'; require_once dirname(__DIR__,3).'/core/Security/AsiloAuthorization.php'; require_once dirname(__DIR__,3).'/infra/Database/Database.php'; require_once dirname(__DIR__,3).'/presentation/layout/AsiloView.php'; require_once dirname(__DIR__,2).'/autenticacao/services/AsiloAutenticacaoService.php'; require_once dirname(__DIR__,2).'/usuarios/repository/AsiloUsuarioRepository.php'; require_once dirname(__DIR__).'/repository/AsiloFamiliarRepository.php'; require_once dirname(__DIR__).'/services/AsiloFamiliarService.php';
final class AsiloFamiliarController { private PDO $pdo; private AsiloSession $session; private AsiloAutenticacaoService $auth; private AsiloFamiliarService $familiares; private AsiloFamiliarRepository $repo;
 public function __construct(){ $this->session=new AsiloSession();$pdo=PDOMysqli::connection();$this->pdo=$pdo;$this->auth=new AsiloAutenticacaoService(new AsiloUsuarioRepository($pdo),$this->session);$this->repo=new AsiloFamiliarRepository($pdo);$this->familiares=new AsiloFamiliarService($this->repo); }
 public function listar():void{$u=$this->permitir(['Administrador']);$this->view('lista.php',['titulo'=>'Familiares','usuarioAtual'=>$u,'familiares'=>$this->familiares->listar(),'csrfToken'=>CsrfToken::obter('asilosoft_familiares'),'secaoAtual'=>'idosos']);}
 public function novo():void{$u=$this->permitir(['Administrador']);$this->form($u,null);}
 public function editar():void{$u=$this->permitir(['Administrador']);$f=$this->familiares->buscar($this->id());if(!$f)$this->notFound();$this->form($u,$f);}
 public function salvar():never{$this->permitir(['Administrador']);$id=($_GET['route']??'')==='familiares-atualizar'?$this->id():null;try{$this->familiares->salvar($_POST,$id);$this->session->flash('sucesso','Familiar salvo com sucesso.');$this->go('familiares');}catch(DomainException $e){$this->session->flash('erro',$e->getMessage());$this->go($id?'familiares-editar':'familiares-novo',$id?['id'=>$id]:[]);}}
 public function vincular():never{$this->permitir(['Administrador']);$idoso=$this->id();try{$this->familiares->vincular($idoso,(int)filter_var($_POST['familiar_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]),$_POST);$this->session->flash('sucesso','Familiar vinculado.');}catch(DomainException $e){$this->session->flash('erro',$e->getMessage());}$this->go('idosos-ficha',['id'=>$idoso]);}
 public function desvincular():never{$this->permitir(['Administrador']);$idoso=$this->id();try{$this->familiares->desvincular($idoso,(int)filter_var($_POST['familiar_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]));$this->session->flash('sucesso','Vínculo removido.');}catch(DomainException $e){$this->session->flash('erro',$e->getMessage());}$this->go('idosos-ficha',['id'=>$idoso]);}
 public function meusIdosos():void{$u=$this->permitir(['Familiar']);$this->view('meus_idosos.php',['titulo'=>'Meus idosos','usuarioAtual'=>$u,'idosos'=>$this->repo->idososDoUsuario((int)$u['id']),'secaoAtual'=>'familiares']);}
 public function acompanhamento():void{$u=$this->permitir(['Familiar']);$id=$this->id();$reg=$this->repo->acompanhamentosPublicos((int)$u['id'],$id);if($reg===null)$this->forbidden($u);$this->view('acompanhamento.php',['titulo'=>'Acompanhamento','usuarioAtual'=>$u,'registros'=>$reg,'secaoAtual'=>'familiares']);}
 private function form(array $u,?array $f):void{$this->view('formulario.php',['titulo'=>$f?'Editar familiar':'Novo familiar','usuarioAtual'=>$u,'familiar'=>$f,'contas'=>$this->repo->contasDisponiveis($f['id']??null),'csrfToken'=>CsrfToken::obter('asilosoft_familiares'),'secaoAtual'=>'idosos']);} private function permitir(array $p):array{try{$u=AsiloAuthorization::permitir($this->auth->usuarioAtual(),$p);$contexto=$this->pdo->prepare('SET @asilosoft_usuario_id = :id');$contexto->execute(['id'=>(int)$u['id']]);return $u;}catch(RuntimeException $e){if($e->getMessage()==='AUTHENTICATION_REQUIRED')$this->go('login');$this->forbidden($this->auth->usuarioAtual());}} private function view(string $f,array $d):void{AsiloView::render(dirname(__DIR__).'/view/'.$f,$d+['modoDemonstracao'=>false]);} private function id():int{$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);if(!$id||$id<1)$this->notFound();return $id;} private function go(string $r,array $q=[]):never{header('Location: ?'.http_build_query(['route'=>$r]+$q),true,303);exit;} private function notFound():never{http_response_code(404);$this->view('../../../presentation/components/asiloNaoEncontrado.php',['titulo'=>'Página não encontrada']);exit;} private function forbidden(?array $u):never{http_response_code(403);AsiloView::render(dirname(__DIR__,3).'/presentation/components/asiloAcessoNegado.php',['titulo'=>'Acesso negado','usuarioAtual'=>$u,'modoDemonstracao'=>false]);exit;}}
